('pocitace-telefony', '{"cs":"Počítače a telefony","en":"Computers and phones"}'::jsonb, '{"cs":"Notebooky, tablety, mobilní telefony, monitory, tiskárny a síťové prvky. Nastavení a přenos dat na prodejně.","en":"Laptops, tablets, phones, monitors, printers and networking. Set-up and data transfer in store."}'::jsonb, 3),
